mapper.update:
UPDATE diary SET title = #{title}, content = #{content}, mood_type = #{moodType},
                 sentiment_score = #{sentimentScore}, sentiment_label = #{sentimentLabel}, sentiment_emotion = #{sentimentEmotion}
WHERE id = #{id} AND user_id = #{userId} AND is_deleted = 0

mapper.select:
SELECT dk.word   
FROM diary_keyword dk
JOIN diary d ON dk.diary_id = d.id   
WHERE d.user_id = #{userId}   
AND d.is_deleted = 0   
AND DATE(d.created_at) BETWEEN #{start} AND #{end}   
GROUP BY dk.word
ORDER BY COUNT(*) DESC
LIMIT #{limit}
